//
//  Simple Particle System - Vertex Shader
//  Native Metal Shader
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut vertex_main(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

passes.fragmentSource:
//
//  Simple Particle System - Fragment Shader
//  Native Metal Shader - Simpler version without compute
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float particle_amount;
    float particle_speed;
    float particle_size;
    float color_variation;
};

float random(float2 co) {
    return fract(sin(dot(co, float2(12.9898, 78.233))) * 43758.5453);
}

fragment float4 fragment_main(
    float4 position [[position]],
    float2 texCoord [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    // Sample original image
    float4 color = sourceTexture.sample(textureSampler, texCoord);

    float time = float(uniforms.FrameCount) * uniforms.particle_speed * 0.01;
    float3 particleGlow = float3(0.0);

    // Create particle grid
    float2 gridSize = float2(30.0, 20.0);
    float2 gridPos = texCoord * gridSize;
    float2 cellPos = fract(gridPos);
    float2 cellId = floor(gridPos);

    // Animated particle position
    float angle = time + random(cellId) * 6.28;
    float radius = 0.3 + sin(time * 2.0 + random(cellId + float2(1.0, 0.0)) * 6.28) * 0.2;

    float2 particlePos = float2(
        0.5 + cos(angle) * radius,
        0.5 + sin(angle) * radius
    );

    // Distance to particle
    float dist = length(cellPos - particlePos);

    // Particle glow
    float particleSize = uniforms.particle_size * 0.015;
    float glow = smoothstep(particleSize * 2.0, 0.0, dist);

    // Only show some particles
    float showParticle = step(1.0 - uniforms.particle_amount, random(cellId + float2(0.5)));

    // Particle color
    float colorPhase = time + random(cellId) * 6.28;
    float3 particleColor = float3(
        sin(colorPhase) * 0.5 + 0.5,
        sin(colorPhase + 2.094) * 0.5 + 0.5,
        sin(colorPhase + 4.189) * 0.5 + 0.5
    );
    particleColor = mix(float3(1.0), particleColor, uniforms.color_variation);

    particleGlow += particleColor * glow * showParticle;

    // Add particles to image
    color.rgb += particleGlow;

    return color;
}
